css:
    /* ============================================================
       BASE — optimized for A4, ~25 items per page
       ============================================================ */
    * { box-sizing: border-box; }

    .print-format,
    .print-format table {
        font-size: 9px !important;
        color: black !important;
        line-height: 1.3 !important;
    }

    .print-format p { margin: 2px 0 !important; }

    .print-format table td,
    .print-format table th {
        padding-top: 2px !important;
        padding-bottom: 2px !important;
    }

    /* ===== Main Header: 3-column ===== */
    .main-header-table {
        border-collapse: collapse;
        width: 100%;
        margin-bottom: 4px !important;
        border: 2px solid black !important;
    }

    .main-header-table > tbody > tr > td,
    .main-header-table > tr > td {
        border: 1px solid black !important;
        vertical-align: top;
        padding: 4px 5px !important;
    }

    .co-info-cell {
        width: 22%;
        vertical-align: top;
        text-align: left;
        padding: 4px 5px !important;
        border: 1px solid black !important;
    }

    .info-box-cell {
        width: 39%;
        vertical-align: top;
        padding: 4px 5px !important;
        border: 1px solid black !important;
    }

   .co-logo {
    max-height: 65px;
    max-width: 120px;
    object-fit: contain;
    margin-bottom: 2px !important;
    display: block;
}

.co-name {
    font-size: 10px !important;
    font-weight: bold;
    color: #1a5ca8 !important;
    display: block;
    margin-bottom: 1px !important;
    line-height: 1.1 !important;
}

.co-detail {
    font-size: 7.5px !important;
    color: black !important;
    display: block;
    line-height: 1.05 !important;
    margin: 0 !important;
    padding: 0 !important;
}

    .w-100 { width: 100%; }
    .bold  { font-weight: bold; }
    .text-underline { text-decoration: underline; }
    .text-center { text-align: center; }
    .text-right  { text-align: right; }
    .text-left   { text-align: left; }

    /* ===== Title ===== */
    .pf-title {
        width: fit-content;
        border: 1px solid black;
        border-radius: 6px;
        margin: 0 auto 4px auto;
        padding: 1px 6px !important;
        font-size: 11px !important;
    }

    /* ===== Header 2-Box Row ===== */
    .header-2boxes {
        border-collapse: separate;
        border-spacing: 6px 0;
        margin-top: 4px !important;
        margin-bottom: 4px !important;
        width: 100%;
    }

    .box {
        width: 50%;
        border: 1px solid black;
        vertical-align: top;
        padding: 4px !important;
    }

    .box-title {
        font-weight: bold;
        font-size: 9px !important;
        text-align: center;
        border: 1px solid black;
        padding: 2px 4px !important;
        margin-bottom: 3px !important;
    }

    .box-table { border-collapse: collapse; width: 100%; }

    .box-table td {
        padding: 1px 4px !important;
        vertical-align: middle;
        font-size: 9px !important;
    }

    .box-table .lbl {
        font-weight: bold;
        white-space: nowrap;
        width: 30%;
    }

    .box-table .val {
        width: 40%;
        text-align: center;
        border-bottom: 1px dotted #555;
    }

    .box-table .ar {
        direction: rtl;
        text-align: right;
        font-weight: bold;
        white-space: nowrap;
        width: 30%;
    }

    /* ===== Items Table ===== */
    .items-table-container {
        border: 1px solid black;
        padding: 0 !important;
        margin-top: 4px !important;
    }

    .items-table {
        border-collapse: collapse;
        width: 100%;
    }

    .items-table td {
        border: 1px solid black;
        padding: 2px 3px !important;
        font-size: 9px !important;
    }

    .items-header td {
        background-color: #e8e8e8;
        font-weight: bold;
        text-align: center;
        font-size: 9px !important;
        padding: 3px 2px !important;
        line-height: 1.2 !important;
    }

    /* item rows */
    .items-table tbody tr td {
        padding: 1px 3px !important;
        line-height: 1.25 !important;
    }

    /* ===== Total / Footer rows ===== */
    .total-row td {
        padding: 2px 6px !important;
        border-top: 1px solid #aaa;
        font-size: 9px !important;
    }

    .grand-total-row td {
        padding: 3px 6px !important;
        border-top: 2px solid black;
        border-bottom: 2px solid black;
        font-size: 10px !important;
    }

    .grand-total-val {
        font-size: 11px !important;
        font-weight: bold;
    }

    .words-row td {
        padding: 4px 6px !important;
        border-top: 1px solid #ccc;
        font-size: 9px !important;
        font-style: italic;
    }

    /* ===== Bank Section ===== */
    .bank-section {
        border-collapse: separate;
        border-spacing: 6px 0;
        margin-top: 5px !important;
        margin-bottom: 5px !important;
        width: 100%;
    }

    .bank-box {
        width: 50%;
        border: 1px solid black;
        vertical-align: top;
        padding: 5px !important;
    }

    .bank-title {
        text-decoration: underline;
        font-weight: bold;
        font-size: 9px !important;
        margin-bottom: 2px !important;
    }

    .bank-subtitle {
        font-size: 8px !important;
        color: #444;
        margin-bottom: 3px !important;
    }

    .bank-info {
        font-size: 8.5px !important;
        line-height: 1.5 !important;
    }

    .bank-appreciation {
        font-size: 8.5px !important;
        font-style: italic;
        margin-top: 5px !important;
    }

    /* ===== Remarks ===== */
    .remarks-section {
        margin-top: 5px !important;
        margin-bottom: 5px !important;
        border-collapse: collapse;
        width: 100%;
    }

    .remarks-section td {
        border: 1px solid black;
        padding: 5px !important;
    }

    .remarks-title {
        font-weight: bold;
        font-size: 9px !important;
        text-align: center;
        border: 1px solid black;
        padding: 2px 4px !important;
        margin-bottom: 4px !important;
    }

    .remarks-box {
        position: relative;
        padding-bottom: 20px !important;
    }

    .remarks-content {
        min-height: 50px;
        padding: 3px !important;
        font-size: 9px !important;
    }

    .disclaimer-text {
        position: absolute;
        bottom: 4px;
        left: 5px;
        right: 5px;
        font-size: 7.5px !important;
        font-style: italic;
        border-top: 1px dotted #999;
        padding-top: 2px !important;
        color: #333 !important;
    }

    /* ===== Signatures ===== */
    .final-signatures {
        margin-top: 10px !important;
        border-collapse: separate;
        border-spacing: 30px 0;
        page-break-inside: avoid;
        width: 100%;
    }

    .sign-box {
        width: 50%;
        text-align: center;
        vertical-align: bottom;
    }

    .sign-title {
        font-weight: bold;
        font-size: 9px !important;
        margin-bottom: 18px !important;
    }

    .sign-space {
        border-bottom: 1px solid black;
        width: 75%;
        margin: 0 auto 4px auto;
        height: 20px;
    }

    .sign-label { font-size: 8.5px !important; }
    
    
    @media (max-width: 767px) {
        .print-format {
            padding: 20px !important;
        }
    }
